from collections import OrderedDict


class LRUCache:
    """A fixed-capacity LRU cache.

    ``get(key)`` returns the cached value or ``None`` and marks the key as
    recently used.  ``put(key, value)`` inserts or updates a key and marks it
    as recently used.  When an insert would exceed ``capacity``, the least
    recently used key is evicted first.  ``len(cache)`` is the number of keys.
    """

    def __init__(self, capacity):
        capacity = int(capacity)
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data
